#!/usr/bin/env node
// Default web, native, watch, store and splash assets from the retained brand artwork.
// Run after app-icons.mjs. --check compares generated bytes without writing.
import fs from 'node:fs'
import path from 'node:path'
import { fileURLToPath } from 'node:url'
import { draw, png, pngInfo, ROOT, DENSITIES } from './app-icons.mjs'
import { brandPixels } from './brand-raster.mjs'
const repo = path.dirname(ROOT), check = process.argv.includes('--check'), bad = []
const variant = { id: 'default' }
function write(file, body) {
  if (check) { if (!fs.existsSync(file) || !fs.readFileSync(file).equals(body)) bad.push(path.relative(repo, file)); return }
  fs.mkdirSync(path.dirname(file), { recursive: true }); fs.writeFileSync(file, body)
}
const icon = (file, size) => write(file, draw(variant, size))
const walk = dir => fs.readdirSync(dir, { withFileTypes: true }).flatMap(e => e.isDirectory() ? walk(path.join(dir, e.name)) : [path.join(dir, e.name)])
for (const dir of ['ios/App/App/Assets.xcassets/AppIcon.appiconset', 'ios/App/Watch/Assets.xcassets/AppIcon.appiconset']) {
  const catalog = JSON.parse(fs.readFileSync(path.join(ROOT, dir, 'Contents.json'), 'utf8'))
  for (const entry of catalog.images.filter(i => i.filename)) icon(path.join(ROOT, dir, entry.filename), Math.round(parseFloat(entry.size) * parseFloat(entry.scale || '1')))
}
for (const [dpi, scale] of Object.entries(DENSITIES)) {
  const dir = path.join(ROOT, 'android/app/src/main/res/mipmap-' + dpi)
  icon(path.join(dir, 'ic_launcher.png'), Math.round(48 * scale))
  write(path.join(dir, 'ic_launcher_round.png'), draw(variant, Math.round(48 * scale), { round: true }))
  icon(path.join(dir, 'ic_launcher_foreground.png'), Math.round(108 * scale))
  const size = Math.round(108 * scale), fill = Buffer.alloc(size * size * 3)
  for (let i = 0; i < fill.length; i += 3) { fill[i] = 7; fill[i + 1] = 16; fill[i + 2] = 28 }
  write(path.join(dir, 'ic_launcher_background.png'), png(size, size, fill, 3))
}
for (const dir of ['public', '../website']) {
  for (const size of dir === 'public' ? [180, 512] : [48, 96, 180, 192, 512]) icon(path.resolve(ROOT, dir, 'icon-' + size + '.png'), size)
  // An ICO directory containing a standards-compliant PNG image.
  const data = draw(variant, 48), header = Buffer.alloc(22)
  header.writeUInt16LE(1, 2); header.writeUInt16LE(1, 4); header[6] = 48; header[7] = 48
  header.writeUInt16LE(1, 10); header.writeUInt16LE(32, 12); header.writeUInt32LE(data.length, 14); header.writeUInt32LE(22, 18)
  write(path.resolve(ROOT, dir, 'favicon.ico'), Buffer.concat([header, data]))
}
const size = 512, mask = Buffer.alloc(size * size * 3), inset = 52, inner = size - inset * 2, art = brandPixels(inner)
for (let i = 0; i < mask.length; i += 3) { mask[i] = 7; mask[i + 1] = 16; mask[i + 2] = 28 }
for (let y = 0; y < inner; y++) art.copy(mask, ((y + inset) * size + inset) * 3, y * inner * 3, (y + 1) * inner * 3)
write(path.join(ROOT, 'public/icon-maskable.png'), png(size, size, mask, 3))
for (const rel of ['fastlane/metadata/android/en-US/images/icon.png', 'watch-zepp/assets/common.s/icon.png', 'watch-zepp/assets/common.r/icon.png', 'frontend/garmin/resources/drawables/launcher_icon.png']) {
  const file = path.join(repo, rel); icon(file, pngInfo(fs.readFileSync(file)).width)
}
// Native launch screens have a calm background with the supplied icon centered.
for (const root of ['android/app/src/main/res', 'ios/App/App/Assets.xcassets/Splash.imageset']) {
  for (const file of walk(path.join(ROOT, root)).filter(f => /(?:splash.*\.png)$/i.test(path.basename(f)))) {
    const { width, height } = pngInfo(fs.readFileSync(file)), canvas = Buffer.alloc(width * height * 3)
    for (let i = 0; i < canvas.length; i += 3) { canvas[i] = 7; canvas[i + 1] = 16; canvas[i + 2] = 28 }
    const size = Math.max(1, Math.round(Math.min(width, height) * .32)), art = brandPixels(size), left = Math.floor((width - size) / 2), top = Math.floor((height - size) / 2)
    for (let y = 0; y < size; y++) art.copy(canvas, ((y + top) * width + left) * 3, y * size * 3, (y + 1) * size * 3)
    write(file, png(width, height, canvas, 3))
  }
}
const normalized = fs.readFileSync(path.join(ROOT, 'resources/brand-icon.png'))
const notification = brandPixels(96), stencil = Buffer.alloc(96 * 96 * 4)
for (let i = 0; i < 96 * 96; i++) {
  stencil[i * 4] = stencil[i * 4 + 1] = stencil[i * 4 + 2] = 255
  stencil[i * 4 + 3] = notification[i * 3 + 2] > 100 ? Math.min(255, Math.max(0, (notification[i * 3 + 2] - notification[i * 3]) * 2)) : 0
}
write(path.join(ROOT, 'android/app/src/main/res/drawable-nodpi/brand_notification.png'), png(96, 96, stencil, 4))
write(path.join(ROOT, 'public/badge-96.png'), png(96, 96, stencil, 4))
write(path.join(ROOT, 'android/wear/src/main/res/drawable-nodpi/brand_notification.png'), png(96, 96, stencil, 4))
icon(path.join(ROOT, 'android/wear/src/main/res/drawable-nodpi/brand_launcher.png'), 324)
write(path.join(ROOT, 'android/wear/src/main/res/drawable/ic_launcher_foreground.xml'), Buffer.from('<?xml version="1.0" encoding="utf-8"?>\n<inset xmlns:android="http://schemas.android.com/apk/res/android" android:drawable="@drawable/brand_launcher" android:inset="16.7%" />\n'))
write(path.join(ROOT, 'android/app/src/main/res/drawable/ic_stat_dumbbell.xml'), Buffer.from('<?xml version="1.0" encoding="utf-8"?>\n<bitmap xmlns:android="http://schemas.android.com/apk/res/android" android:src="@drawable/brand_notification" android:gravity="center" />\n'))
write(path.join(ROOT, 'android/app/src/main/res/drawable-v24/ic_launcher_foreground.xml'), Buffer.from('<?xml version="1.0" encoding="utf-8"?>\n<bitmap xmlns:android="http://schemas.android.com/apk/res/android" android:src="@mipmap/ic_launcher_foreground" android:gravity="center" />\n'))
write(path.join(ROOT, 'android/app/src/main/res/drawable/ic_launcher_background.xml'), Buffer.from('<?xml version="1.0" encoding="utf-8"?>\n<bitmap xmlns:android="http://schemas.android.com/apk/res/android" android:src="@mipmap/ic_launcher_background" android:gravity="center" />\n'))
write(path.join(ROOT, 'resources/icon.png'), normalized)
write(path.join(ROOT, 'resources/icon.svg'), Buffer.from(`<svg xmlns="http://www.w3.org/2000/svg" width="1024" height="1024"><image width="1024" height="1024" href="data:image/png;base64,${normalized.toString('base64')}"/></svg>\n`))
if (bad.length) { console.error('Brand assets out of date:\n' + bad.join('\n')); process.exitCode = 1 }
else console.log(check ? 'Brand assets up to date' : 'Brand assets written')
